/**
 * Token source layer — single point of access to Figma design tokens.
 *
 * All pages read tokens through this module. When the project migrates
 * to CSS custom properties generated by a build pipeline, only this
 * file needs to change — page code stays untouched.
 */

import lightJson from "./figma/mode-light.json";
import darkJson from "./figma/mode-dark.json";
import customDesktopJson from "./figma/custom-desktop.json";
import themeTypoJson from "./figma/theme-typography.json";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface ColorToken {
  name: string;
  hex: string;
  alpha: number;
  /** Ready-to-use CSS value: "#RRGGBB" or "rgba(r, g, b, a)" */
  cssValue: string;
  description: string;
}

export interface ColorGroup {
  label: string;
  tokenNames: string[];
}

export interface TypographyToken {
  role: string;
  fontFamily: string;
  fontSize: number;
  lineHeight: number;
  fontWeight: number;
  letterSpacing: number;
}

export interface FontFamily {
  key: string;
  name: string;
}

export interface TextScale {
  size: string;
  fontSize: number;
  lineHeight: number;
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

interface FigmaColorValue {
  components: number[];
  alpha: number;
  hex: string;
}

interface FigmaColorEntry {
  $type: string;
  $value: FigmaColorValue | string;
  $description?: string;
}

function resolveColorValue(v: FigmaColorValue): {
  hex: string;
  alpha: number;
  cssValue: string;
} {
  const { hex, alpha, components } = v;
  if (alpha >= 0.995) {
    return { hex, alpha: 1, cssValue: hex };
  }
  const r = Math.round(components[0]! * 255);
  const g = Math.round(components[1]! * 255);
  const b = Math.round(components[2]! * 255);
  const a = Math.round(alpha * 100) / 100;
  return { hex, alpha: a, cssValue: `rgba(${r}, ${g}, ${b}, ${a})` };
}

function parseBaseTokens(
  json: Record<string, unknown>,
): Map<string, ColorToken> {
  const base = json["base"] as Record<string, FigmaColorEntry> | undefined;
  if (!base) return new Map();

  const map = new Map<string, ColorToken>();
  for (const [name, entry] of Object.entries(base)) {
    if (entry.$type !== "color" || typeof entry.$value === "string") continue;
    const resolved = resolveColorValue(entry.$value);
    map.set(name, {
      name,
      ...resolved,
      description: entry.$description ?? "",
    });
  }
  return map;
}

