// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

const lightTokens = parseBaseTokens(lightJson as Record<string, unknown>);
const darkTokens = parseBaseTokens(darkJson as Record<string, unknown>);

/** Returns a Map<tokenName, ColorToken> for the requested mode. */
export function getSemanticColors(
  mode: "light" | "dark",
): Map<string, ColorToken> {
  return mode === "light" ? lightTokens : darkTokens;
}

/** Returns heading roles from the Custom/Desktop collection. */
export function getTypographyTokens(): TypographyToken[] {
  const json = customDesktopJson as Record<string, unknown>;
  const roles: TypographyToken[] = [];

  for (const [key, value] of Object.entries(json)) {
    if (key.startsWith("$") || typeof value !== "object" || value === null)
      continue;
    const v = value as Record<string, { $value?: unknown }>;
    if (!v["font-family"]) continue;

    roles.push({
      role: key,
      fontFamily: v["font-family"].$value as string,
      fontSize: v["font-size"]?.$value as number,
      lineHeight: v["line-height"]?.$value as number,
      fontWeight: v["font-weight"]?.$value as number,
      letterSpacing: v["letter-spacing"]?.$value as number,
    });
  }

  return roles;
}

/** Returns font family definitions from the Theme collection. */
export function getFontFamilies(): FontFamily[] {
  const font = (themeTypoJson as Record<string, unknown>)["font"] as
    | Record<string, { $value?: string }>
    | undefined;
  if (!font) return [];

  return Object.entries(font)
    .filter(([, v]) => typeof v.$value === "string")
    .map(([key, v]) => ({ key, name: v.$value as string }));
}

/** Returns the text size scale (xs..9xl) from the Theme collection. */
export function getTextScale(): TextScale[] {
  const text = (themeTypoJson as Record<string, unknown>)["text"] as
    | Record<string, Record<string, { $value?: number }>>
    | undefined;
  if (!text) return [];

  const order = [
    "xs", "sm", "base", "lg", "xl",
    "2xl", "3xl", "4xl", "5xl", "6xl", "7xl", "8xl", "9xl",
  ];

  return order
    .filter((s) => text[s])
    .map((size) => ({
      size,
      fontSize: text[size]!["font-size"]?.$value ?? 0,
      lineHeight: text[size]!["line-height"]?.$value ?? 0,
    }));
}
